select energy_manager.load_cards($cards$[
{"id":"p4-b07-018","paper":4,"topic":"Pump Performance","kind":"fact","front":"How is pump shaft power found from the motor input?","back":"Pump shaft power = measured motor input power × motor efficiency at the existing loading.","explain":"Motor input is measured with a portable power analyser. The motor efficiency must be the one at the actual load, because it changes with loading.","flash":false,"source":"BEE Book 4 Ch 07 p142","order":4321},
{"id":"p4-b07-019","paper":4,"topic":"Pump Performance","kind":"problem","front":"A cooling water pump delivers 0.40 m³/s against a total head of 54 m. The measured motor input is 325 kW, motor efficiency 88%, water density 996 kg/m³. Find the hydraulic power, the overall efficiency and the pump efficiency.","back":"Hydraulic power 211 kW; overall efficiency 65%; pump efficiency 74%.","explain":"Pump efficiency is the overall figure divided by motor efficiency, so 65 ÷ 0.88 = 74%. Removing the motor loss isolates the pump's own performance.","flash":false,"source":"BEE Book 4 Ch 07 p142","steps":[{"prompt":"Find the hydraulic power.","answer":"0.40 × 54 × 996 × 9.81 / 1000 = 211 kW","explain":"Hydraulic power = Q × H × ρ × g / 1000, with Q in m³/s and H in metres."},{"prompt":"Find the overall efficiency.","answer":"211 / 325 × 100 = 65%","explain":"Overall efficiency is hydraulic power divided by the measured motor input."},{"prompt":"Find the pump efficiency.","answer":"65 / 0.88 = 74%","explain":"Shaft power = motor input × motor efficiency, so pump efficiency = overall efficiency / motor efficiency."}],"order":4322},
{"id":"p4-b07-020","paper":4,"topic":"Pump Performance","kind":"fact","front":"What is the first step in building a system resistance curve?","back":"Divide the system resistance into static head and dynamic head, then find dynamic head = total head − static head.","explain":"Static head, such as the condenser floor height, does not change with flow. Only the dynamic (friction and equipment) head varies with flow, so that is the part plotted against flow.","flash":false,"source":"BEE Book 4 Ch 07 p143","order":4323},
{"id":"p4-b07-021","paper":4,"topic":"Pump Performance","kind":"fact","front":"Which loop does the chapter choose to draw the system resistance curve, and why?","back":"The condenser loop, because it offers the maximum resistance at full load and has a static head component.","explain":"The condenser and cooler circuits both have high resistance at full load, but only the condenser loop includes a static head (15 m). The curve built on it therefore reflects the largest system resistance with static lift included.","flash":false,"source":"BEE Book 4 Ch 07 p144","order":4324},
{"id":"p4-b07-022","paper":4,"topic":"Pump Performance","kind":"problem","front":"Using the condenser loop (static head 15 m, full-load dynamic head 39 m), find the total head at 50% flow.","back":"Total head 24.75 m (dynamic 9.75 m + static 15 m).","explain":"Dynamic head varies with the square of flow, so 39 × 0.5² = 9.75 m, and the static head stays at 15 m. The system curve is built by repeating this at several flow percentages.","flash":false,"source":"BEE Book 4 Ch 07 p144","steps":[{"prompt":"Write the dynamic head relation.","answer":"Dynamic head = 39 × (% flow)²","explain":"As in the chapter's table, the friction-based dynamic head varies with the square of flow."},{"prompt":"Substitute 50% flow.","answer":"39 × 0.5² = 9.75 m","explain":"Flow is used as a fraction (0.5 for 50%)."},{"prompt":"Add the static head.","answer":"Total head = 9.75 + 15 = 24.75 m","explain":"Static head does not change with flow."}],"order":4325},
{"id":"p4-b07-023","paper":4,"topic":"Pump Performance","kind":"fact","front":"What is the final step of the system-curve method, and what did the example find?","back":"Plot system resistance against flow on the vendor's pump efficiency curves and check whether the operating point is at maximum efficiency. The example found pump system efficiency about 4% lower than design.","explain":"A change in operating conditions moves the system curve, so the actual duty point drifts away from the best-efficiency point. The gap shows how much efficiency has been lost.","flash":true,"source":"BEE Book 4 Ch 07 p144","order":4326},
{"id":"p4-b07-024","paper":4,"topic":"Pump Performance","kind":"fact","front":"In the system-curve example, what are the static head, the full-load dynamic head and the total head?","back":"Static head 15 m; dynamic head 39 m at full load; total head 54 m.","explain":"The total head of 54 m comes from the measured test values. Static head is the condenser floor height, and the dynamic head is the rest of the total.","flash":false,"source":"BEE Book 4 Ch 07 p143","order":4327},
{"id":"p4-b07-025","paper":4,"topic":"Pump Performance","kind":"problem","front":"A circular sump of 8 m diameter takes 10 minutes to fill 1 m of level. Find the pump flow in m³/hr.","back":"About 302 m³/hr.","explain":"Sump area is π × 8² / 4 = 50.3 m², so each metre of level is 50.3 m³ filled in 10 minutes. Six such periods fit in an hour, so the flow is 50.3 × 6 = 302 m³/hr.","flash":false,"source":"BEE Book 4 Ch 07 p145","steps":[{"prompt":"Find the sump area.","answer":"π × 8² / 4 = 50.27 m²","explain":"Area of a circle of diameter 8 m."},{"prompt":"Find the volume for 1 m of level rise.","answer":"50.27 × 1 m = 50.27 m³","explain":"This volume fills in 10 minutes."},{"prompt":"Convert the 10-minute fill to m³/hr.","answer":"50.27 × 60 / 10 = 302 m³/hr","explain":"An hour holds six 10-minute periods."}],"order":4328},
{"id":"p4-b07-026","paper":4,"topic":"Pump Performance","kind":"problem","front":"A motor runs at 415 V, 93 A and power factor 0.89. Find the power drawn by the motor.","back":"About 59.5 kW.","explain":"Three-phase power is √3 × V × I × cos φ. Motor efficiency is not needed here; it is applied later to find the pump shaft power.","flash":false,"source":"BEE Book 4 Ch 07 p146","steps":[{"prompt":"Write the formula.","answer":"P = √3 × V × I × cos φ","explain":"Standard three-phase power formula."},{"prompt":"Substitute the values.","answer":"√3 × 0.415 × 93 × 0.89","explain":"Voltage in kV (415 V = 0.415 kV) gives the power directly in kW."},{"prompt":"Evaluate.","answer":"= 59.5 kW","explain":"This is the motor input power used in the efficiency calculation."}],"order":4329},
{"id":"p4-b07-027","paper":4,"topic":"Pump Performance","kind":"problem","front":"Flow is 302 m³/hr through a 300 mm horizontal pipe, 8 km long, friction factor 0.006, with suction head −2 m. Motor input is 59.5 kW and motor efficiency 0.9. Find the total head and the pump efficiency.","back":"Total head 48.2 m; pump efficiency 74.1%.","explain":"Friction head is 46.2 m, and total head is 46.2 minus the suction head (−2 m), giving 48.2 m. Hydraulic power 39.7 kW divided by shaft power 53.55 kW gives 74.1%.","flash":false,"source":"BEE Book 4 Ch 07 p146","steps":[{"prompt":"Find the pipe velocity.","answer":"v = (302 / 3600) / (π × 0.3² / 4) = 1.19 m/s","explain":"Flow divided by the pipe cross-sectional area."},{"prompt":"Find the friction head.","answer":"h_f = 4 × 0.006 × 1.19² × 8000 / (2 × 9.81 × 0.3) = 46.2 m","explain":"Uses the chapter's 4fLv²/2gD relation; suction piping losses are ignored."},{"prompt":"Find the total head.","answer":"H = 46.2 − (−2) = 48.2 m","explain":"A negative suction head adds to the total head."},{"prompt":"Find hydraulic and shaft power.","answer":"Hydraulic = (302/3600) × 48.2 × 9.81 = 39.7 kW; shaft = 59.5 × 0.9 = 53.55 kW","explain":"Shaft power is the motor input multiplied by motor efficiency."},{"prompt":"Find the pump efficiency.","answer":"39.7 / 53.55 = 74.1%","explain":"Hydraulic power divided by shaft power."}],"order":4330},
{"id":"p4-b07-028","paper":4,"topic":"Pump Performance","kind":"problem","front":"A clear water pump rated 800 m³/hr at 1485 rpm delivers 576 m³/hr with its discharge valve throttled. Discharge pressure is 2 kg/cm² (g), the sump is 4 m below the pump centreline, and motor input is 124 kW at 92% motor efficiency. Find the pump efficiency.","back":"About 33%.","explain":"Total head is 20 − (−4) = 24 m. Hydraulic power is 37.67 kW and shaft power 114 kW, so efficiency is 33%. The low figure reflects the throttled valve, which the next part of the example addresses with speed control.","flash":false,"source":"BEE Book 4 Ch 07 p147","steps":[{"prompt":"Find the total head.","answer":"h_d − h_s = 20 − (−4) = 24 m","explain":"2 kg/cm² = 20 m head, and the sump below the centreline makes the suction head negative."},{"prompt":"Find the hydraulic power.","answer":"576 × 24 × 1000 × 9.81 / (3600 × 1000) = 37.67 kW","explain":"Q in m³/s is 576 / 3600."},{"prompt":"Find the shaft power.","answer":"124 × 0.92 = 114 kW","explain":"Motor input multiplied by motor efficiency."},{"prompt":"Find the pump efficiency.","answer":"37.67 / 114 × 100 = 33%","explain":"Hydraulic power divided by shaft power."}],"order":4331},
{"id":"p4-b07-029","paper":4,"topic":"Pump Performance","kind":"fact","front":"A pump must deliver 500 to 700 m³/hr from an 800 m³/hr unit. What is the most energy-efficient way to vary the flow?","back":"Speed control with a VSD (variable frequency drive) or a hydraulic coupling, rather than throttling the discharge valve.","explain":"The chapter's solution picks speed control. Throttling keeps the pump at full speed and wastes energy, whereas speed reduction cuts shaft power sharply, as the next part of the example shows.","flash":false,"source":"BEE Book 4 Ch 07 p147","order":4332},
{"id":"p4-b07-030","paper":4,"topic":"Pump Performance","kind":"problem","front":"Using the same 800 m³/hr pump at 1485 rpm with 114 kW shaft power at full speed, find the speed and shaft power needed to deliver 550 m³/hr.","back":"Speed about 1021 rpm; shaft power about 37 kW.","explain":"Flow is proportional to speed, and power varies with the cube of speed, so 114 × (1021/1485)³ ≈ 37 kW, matching the book's answer.","flash":false,"source":"BEE Book 4 Ch 07 p147","steps":[{"prompt":"Find the reduced speed (flow is proportional to speed).","answer":"N₁ = 1485 × 550 / 800 = 1021 rpm","explain":"Capacity is proportional to N."},{"prompt":"Write the power relation for the speed change.","answer":"P₂ = P₁ × (N₂ / N₁)³","explain":"Shaft power varies with the cube of speed, as the chapter's speed example shows."},{"prompt":"Substitute.","answer":"P = 114 × (1021 / 1485)³ = 37 kW","explain":"114 kW is the shaft power at full speed from the previous part."}],"order":4333},
{"id":"p4-b07-031","paper":4,"topic":"Pump Performance","kind":"problem","front":"A centrifugal pump delivers 30 m³/hr at 1440 rpm with 3.4 kg/cm² discharge pressure, the suction 3 m below the centreline, and pump efficiency 65%. Find the power drawn by the pump.","back":"4.65 kW.","explain":"Total head is 34 + 3 = 37 m. Hydraulic power is 3.02 kW, and dividing by the 65% pump efficiency gives 4.65 kW of shaft power.","flash":false,"source":"BEE Book 4 Ch 07 p148","steps":[{"prompt":"Find the total head.","answer":"Discharge 34 m − suction (−3 m) = 37 m","explain":"3.4 kg/cm² = 34 m of head, and the suction is 3 m below the centreline."},{"prompt":"Find the hydraulic power.","answer":"(30 / 3600) × 37 × 9.81 = 3.02 kW","explain":"Q is converted to m³/s before use."},{"prompt":"Find the shaft power.","answer":"3.02 / 0.65 = 4.65 kW","explain":"Shaft power is hydraulic power divided by pump efficiency."}],"order":4334},
{"id":"p4-b07-032","paper":4,"topic":"Pump Performance","kind":"problem","front":"The pump in the previous case (30 m³/hr, 37 m head, 4.65 kW shaft, 1440 rpm) is slowed by 25% to 1080 rpm. Motor efficiency is 89%. Find the new flow, head, shaft power and motor power.","back":"Flow 22.5 m³/hr; head 20.81 m; shaft power 1.96 kW; motor power 2.2 kW.","explain":"Flow varies with speed, head with its square and power with its cube. A 75% speed ratio gives factors of 0.75, 0.5625 and 0.42.","flash":false,"source":"BEE Book 4 Ch 07 p148","steps":[{"prompt":"Find the speed ratio.","answer":"1080 / 1440 = 0.75","explain":"A 25% reduction leaves 75% of the original speed."},{"prompt":"Find the new flow.","answer":"30 × 0.75 = 22.5 m³/hr","explain":"Flow is proportional to speed."},{"prompt":"Find the new head.","answer":"37 × 0.75² = 20.81 m","explain":"Head varies with the square of speed."},{"prompt":"Find the new shaft power.","answer":"4.65 × 0.75³ = 1.96 kW","explain":"Power varies with the cube of speed."},{"prompt":"Find the motor power.","answer":"1.96 / 0.89 = 2.2 kW","explain":"Motor input equals shaft power divided by motor efficiency."}],"order":4335},
{"id":"p4-b07-033","paper":4,"topic":"Pump Performance","kind":"problem","front":"Water flows at 2 m/s in a 250 mm pipe. A 600 m line (friction factor 0.005) is changed to 300 mm diameter with the same flow. Find the friction head loss in the 300 mm pipe.","back":"About 3.94 m of head.","explain":"Velocity falls to 1.39 m/s in the larger pipe, and friction head depends on v², so it falls sharply. The book quotes 3.94 m.","flash":false,"source":"BEE Book 4 Ch 07 p148","steps":[{"prompt":"Find the velocity in the 300 mm pipe.","answer":"v = 2 × (0.25² / 0.3²) = 1.39 m/s","explain":"Same flow through a larger area means lower velocity."},{"prompt":"Write the friction head formula.","answer":"h_f = 4fLv² / (2gD)","explain":"The chapter's pipe friction relation."},{"prompt":"Substitute the values.","answer":"4 × 0.005 × 600 × 1.39² / (2 × 9.81 × 0.3) = 3.94 m","explain":"Use the same formula for both pipe sizes when comparing losses."}],"order":4336},
{"id":"p4-b07-034","paper":4,"topic":"Pump Performance","kind":"fact","front":"A cooling tower is moved from the roof to ground level, and the pump's friction losses are ignored. Will this save pump energy?","back":"No. The pressure differential across the pump stays the same once friction losses are ignored.","explain":"The chapter's reasoning is that the pump only needs to supply the pressure difference round the circuit. With friction ignored, that difference is unchanged by moving the tower, so no saving results.","flash":false,"source":"BEE Book 4 Ch 07 p148","order":4337},
{"id":"p4-b07-035","paper":4,"topic":"Pump Performance","kind":"fact","front":"How does static head vary with flow in a system curve?","back":"It stays constant. Only the friction (dynamic) head changes with flow, roughly as the square of flow.","explain":"In the chapter's example the static head is 15 m at every flow rate, so the total head rises with flow only because of friction.","flash":false,"source":"BEE Book 4 Ch 07 p149","order":4338},
{"id":"p4-b07-036","paper":4,"topic":"Pump Performance","kind":"problem","front":"A 2 m × 2 m overhead tank rises 1 m in 2 minutes with the outlet closed. What is the pump flow?","back":"120 m³/hr.","explain":"This is the tank filling method: volume rise divided by time, using the tank's internal dimensions.","flash":false,"source":"BEE Book 4 Ch 07 p149","steps":[{"prompt":"Find the volume added.","answer":"2 × 2 × 1 = 4 m³","explain":"Tank area times the level rise."},{"prompt":"Find the flow per minute.","answer":"4 / 2 = 2 m³/min","explain":"Divide the volume by the fill time."},{"prompt":"Convert to m³/hr.","answer":"2 × 60 = 120 m³/hr","explain":"Multiply by 60 minutes per hour."}],"order":4339},
{"id":"p4-b07-037","paper":4,"topic":"Pump Performance","kind":"problem","front":"A pump with 70% efficiency has a hydraulic power of 22 kW. Find the power at the pump shaft.","back":"About 31.4 kW at the pump shaft.","explain":"Shaft power = hydraulic power / efficiency. Motor input would also need the motor efficiency, which the question does not give.","flash":false,"source":"BEE Book 4 Ch 07 p149","steps":[{"prompt":"Write the efficiency relation.","answer":"Pump efficiency = hydraulic power / shaft power","explain":"Definition from the chapter."},{"prompt":"Rearrange and substitute.","answer":"Shaft power = 22 / 0.70 = 31.4 kW","explain":"This is the power at the pump shaft."},{"prompt":"Find the motor input.","answer":"Divide by the motor efficiency (not given) to get motor input.","explain":"Motor input follows from the motor efficiency at the existing load."}],"order":4340},
{"id":"p4-b07-038","paper":4,"topic":"Pump Performance","kind":"problem","front":"A centrifugal pump raises water to a height of 12 m. The same pump handles brine with specific gravity 1.2. To what height is the brine raised?","back":"10 m.","explain":"The pump gives the same pressure rise, and head in metres of liquid scales inversely with specific gravity: 12 / 1.2 = 10 m. This is standard hydraulics rather than a formula printed in the chapter.","flash":false,"source":"BEE Book 4 Ch 07 p149","steps":[{"prompt":"Write the relation between pressure and head.","answer":"Same pressure rise: head × density = constant","explain":"A given pressure corresponds to a head that depends on the liquid's density."},{"prompt":"Use the specific gravity.","answer":"Brine head = 12 / 1.2","explain":"Brine is 1.2 times as dense as water."},{"prompt":"Evaluate.","answer":"= 10 m","explain":"The brine rises to 10 m."}],"order":4341},
{"id":"p4-b07-039","paper":4,"topic":"Pump Performance","kind":"fact","front":"Name two non-intrusive methods of measuring water flow in a pipe.","back":"Ultrasonic (Doppler) flow meter; and the tank filling method (level change in an open tank).","explain":"Ultrasonic meters are described in the chapter as non-invasive. The tank method also avoids cutting into the pipe, but it applies only to open systems such as overhead tanks or sumps.","flash":false,"source":"BEE Book 4 Ch 07 p149","order":4342},
{"id":"p4-b08-001","paper":4,"topic":"Compressor Performance","kind":"fact","front":"Why is a periodic performance assessment of compressors essential?","back":"Compressed air is energy intensive and one of the least energy-efficient utilities. Performance falls over time from poor maintenance and wear, and extra compressors added to cover the loss make it worse. Periodic assessment keeps the cost of compressed air down.","explain":"Without measurement, a plant tends to add compressors instead of fixing the cause of the loss. The assessment finds where the efficiency has dropped.","flash":true,"source":"BEE Book 4 Ch 08 p153","order":4343},
{"id":"p4-b08-002","paper":4,"topic":"Compressor Performance","kind":"fact","front":"Name the four things a compressor performance test finds.","back":"Actual free air delivery (FAD); isothermal power required; volumetric efficiency; specific power requirement.","explain":"The actual values are compared with design or standard values to assess the plant's energy efficiency.","flash":false,"source":"BEE Book 4 Ch 08 p153","order":4344},
{"id":"p4-b08-003","paper":4,"topic":"Compressor Performance","kind":"fact","front":"What is compression ratio?","back":"Absolute discharge pressure of the last stage divided by absolute intake pressure.","explain":"Both pressures must be absolute, not gauge readings. The worked example uses 3.5 kg/cm² (a) over 1.04 kg/cm² (a).","flash":true,"source":"BEE Book 4 Ch 08 p153","order":4345},
{"id":"p4-b08-004","paper":4,"topic":"Compressor Performance","kind":"fact","front":"What is isothermal power?","back":"The least power required to compress air, assuming isothermal (constant temperature) conditions.","explain":"It is the theoretical minimum power for the compression and is the benchmark against which the actual compressor is judged.","flash":false,"source":"BEE Book 4 Ch 08 p153","order":4346},
{"id":"p4-b08-005","paper":4,"topic":"Compressor Performance","kind":"fact","front":"How is isothermal efficiency defined?","back":"The ratio of isothermal power to shaft power (compressor input power).","explain":"The worked example divides isothermal power by compressor input power (86 kW, from 100 kW motor input at 86% drive efficiency). The result shows how close the compressor is to ideal isothermal compression.","flash":true,"source":"BEE Book 4 Ch 08 p153","order":4347},
{"id":"p4-b08-006","paper":4,"topic":"Compressor Performance","kind":"fact","front":"How is volumetric efficiency defined?","back":"The ratio of free air delivered to the compressor's swept (displacement) volume.","explain":"It shows how much of the cylinder's swept volume is delivered as free air at the same time-based rate. Both values are expressed per minute in the worked example.","flash":false,"source":"BEE Book 4 Ch 08 p153","order":4348},
{"id":"p4-b08-007","paper":4,"topic":"Compressor Performance","kind":"fact","front":"How is specific power requirement defined?","back":"Power consumption (kW) divided by the volume delivered at ambient conditions, such as m³/hr.","explain":"A lower specific power means less energy is used per unit of air delivered. The worked example gives 100 kW for 1407.6 m³/hr.","flash":false,"source":"BEE Book 4 Ch 08 p153","order":4349},
{"id":"p4-b08-008","paper":4,"topic":"Compressor Performance","kind":"fact","front":"What is the principle of the nozzle method for measuring free air delivery?","back":"Air from the receiver discharges to the atmosphere through a specially shaped nozzle. Sonic flow sets in at the throat (Mach number = 1), so the flow is known from the nozzle's characteristics.","explain":"When receiver pressure is held constant for reasonable intervals, the compressor's output equals the nozzle flow. The nozzle therefore acts as the measuring device.","flash":true,"source":"BEE Book 4 Ch 08 p154","order":4350},
{"id":"p4-b08-009","paper":4,"topic":"Compressor Performance","kind":"fact","front":"What readings are taken in the nozzle test, and at what pressure levels?","back":"At 40%, 60%, 100% and 110% of discharge pressure: receiver pressure; pressure and temperature before the nozzle; pressure drop across the nozzle; compressor speed; and kW, kWh and amps drawn.","explain":"Testing at several pressures shows how FAD and power change across the operating range. The system must be stabilised before readings are taken.","flash":false,"source":"BEE Book 4 Ch 08 p154","order":4351},
{"id":"p4-b08-010","paper":4,"topic":"Compressor Performance","kind":"fact","front":"What instruments are needed for the nozzle test?","back":"Thermometers or thermocouples; pressure gauges or manometers; differential pressure gauges or manometers; standard nozzle; psychrometer; tachometer or stroboscope; electrical demand analyser.","explain":"The temperature and pressure readings give the inlet and nozzle conditions used in the FAD calculation. The electrical analyser gives the power readings.","flash":false,"source":"BEE Book 4 Ch 08 p154","order":4352},
{"id":"p4-b08-011","paper":4,"topic":"Compressor Performance","kind":"fact","front":"Which nozzle size is recommended for a capacity of 1000 m³/hr?","back":"125 mm, for the capacity range 750 to 2000 m³/hr.","explain":"Nozzle size rises with capacity. Pick the row whose capacity range contains the expected flow. For example, 3 to 9 m³/hr uses a 10 mm nozzle and 300 to 450 m³/hr uses 80 mm.","flash":false,"source":"BEE Book 4 Ch 08 p154","order":4353},
{"id":"p4-b08-012","paper":4,"topic":"Compressor Performance","kind":"fact","front":"Which standard gives the flow nozzle profile for the nozzle test, and which code covers testing of positive displacement compressors?","back":"IS 10431:1994 (airflow measurement of compressors and exhausters by nozzles) gives the nozzle profile. IS 5456:1985 is the code of practice for testing positive displacement air compressors and exhausters.","explain":"Both are listed as references in the chapter. They are the Indian standards to quote when specifying the test.","flash":false,"source":"BEE Book 4 Ch 08 p154","order":4354},
{"id":"p4-b08-013","paper":4,"topic":"Compressor Performance","kind":"fact","front":"In the nozzle FAD formula, what is the flow coefficient k and what gas constant is used for air?","back":"k is the flow coefficient as per IS 10431 (assumed as 1 in the worked example). The gas constant for air is 287.1 J/kg·K (287 is used in the example).","explain":"The formula uses the nozzle diameter, the pressure drop across the nozzle, and the absolute pressure and temperature before the nozzle. The inlet conditions are then used to convert the result to free air.","flash":false,"source":"BEE Book 4 Ch 08 p155","order":4355},
{"id":"p4-b08-014","paper":4,"topic":"Compressor Performance","kind":"fact","front":"When is the pump-up (receiver filling) method used for FAD?","back":"Where the elaborate nozzle method is difficult to deploy. It is less accurate than the nozzle method.","explain":"It is done on the shop floor with a stopwatch and the receiver, so it is a practical check rather than a precision test.","flash":false,"source":"BEE Book 4 Ch 08 p158","order":4356},
{"id":"p4-b08-015","paper":4,"topic":"Compressor Performance","kind":"fact","front":"What are the first steps of the pump-up test?","back":"Isolate the compressor and its receiver by closing or blanking the isolation valve. Open the drain and empty the receiver and pipeline of water. Close the drain, start the compressor, and time the rise from initial pressure P₁ to normal operating pressure P₂.","explain":"Isolation keeps the test air confined to the receiver and piping. Emptying the water first makes sure the stored volume starts from a known state.","flash":true,"source":"BEE Book 4 Ch 08 p158","order":4357},
{"id":"p4-b08-016","paper":4,"topic":"Compressor Performance","kind":"fact","front":"Which volume is used in the pump-up formula?","back":"The storage volume in m³: the receiver, the aftercooler and the delivery piping together.","explain":"Hold-up volume in pipes and coolers must be included. The worked example's total is 8.322 m³, which is the 7.79 m³ receiver plus 0.4974 m³ of hold-up.","flash":false,"source":"BEE Book 4 Ch 08 p158","order":4358},
{"id":"p4-b08-017","paper":4,"topic":"Compressor Performance","kind":"fact","front":"What temperature correction applies to pump-up FAD when the discharge air is hotter than ambient?","back":"Multiply the measured FAD by (273 + ambient °C) / (273 + discharge °C), which gives a factor below 1 for hot discharge air.","explain":"Hot air occupies more volume, so the free air figure is reduced to ambient conditions. The chapter prints the ratio with the temperatures in the other order, so keep the physical direction in mind when applying it.","flash":false,"source":"BEE Book 4 Ch 08 p158","order":4359},
{"id":"p4-b08-018","paper":4,"topic":"Compressor Performance","kind":"problem","front":"A nozzle of 0.08 m diameter (k = 1) sits downstream of a receiver. The receiver pressure is 3.5 kg/cm² (a); inlet is 1.04 kg/cm² (a) at 303 K; before the nozzle it is 1.08 kg/cm² (a) at 313 K; the pressure drop across the nozzle is 0.036 kg/cm². Find the free air delivered in m³/hr.","back":"About 0.391 m³/s, which is 1407.6 m³/hr.","explain":"Nozzle flow is found from the pressure drop, the pressure and temperature before the nozzle, the gas constant and the nozzle area. It is then converted to inlet conditions. This FAD value is the input to the isothermal power and efficiency calculations.","flash":false,"source":"BEE Book 4 Ch 08 p157","steps":[{"prompt":"Find the nozzle area.","answer":"π/4 × 0.08² = 0.00503 m²","explain":"Area from the nozzle diameter."},{"prompt":"Substitute into the nozzle FAD formula with k = 1.","answer":"Free air delivered ≈ 0.391 m³/s","explain":"Uses the pressure drop 0.036, pressure before nozzle 1.08 kg/cm² (a), temperature before nozzle 313 K, inlet 303 K and 1.04 kg/cm² (a), and gas constant 287."},{"prompt":"Convert to m³/hr.","answer":"0.391 × 3600 = 1407.6 m³/hr","explain":"Hourly FAD for the next steps."}],"order":4360},
{"id":"p4-b08-019","paper":4,"topic":"Compressor Performance","kind":"problem","front":"Using FAD 1407.6 m³/hr, intake pressure 1.04 kg/cm² (a) and receiver pressure 3.5 kg/cm² (a), find the isothermal power.","back":"About 48.34 kW.","explain":"Isothermal power = P₁ × Q × ln(r) / 36.7, with P₁ in kg/cm² (a) and Q in m³/hr, so the answer is in kW. The compression ratio r = 3.36.","flash":false,"source":"BEE Book 4 Ch 08 p157","steps":[{"prompt":"Write the formula.","answer":"P_iso (kW) = P₁ × Q₁ × ln r / 36.7","explain":"Chapter formula for isothermal power."},{"prompt":"Find the compression ratio.","answer":"3.5 / 1.04 = 3.36","explain":"Both pressures are absolute."},{"prompt":"Substitute and evaluate.","answer":"1.04 × 1407.6 × ln 3.36 / 36.7 = 48.34 kW","explain":"The natural log of 3.36 is about 1.212."}],"order":4361},
{"id":"p4-b08-020","paper":4,"topic":"Compressor Performance","kind":"problem","front":"Isothermal power is 48.34 kW. The motor input is 100 kW and the motor and drive efficiency is 86%. Find the isothermal efficiency.","back":"About 56%.","explain":"Compressor input is 100 × 0.86 = 86 kW, so isothermal efficiency is 48.34 / 86 × 100 = 56%. That is well below ideal, which is what the test is meant to reveal.","flash":false,"source":"BEE Book 4 Ch 08 p157","steps":[{"prompt":"Find the compressor input power.","answer":"100 kW × 0.86 = 86 kW","explain":"Motor and drive losses are removed to get the compressor input."},{"prompt":"Find the isothermal efficiency.","answer":"48.34 / 86 × 100 = 56%","explain":"Isothermal power divided by compressor input power."},{"prompt":"Check the result against the definition.","answer":"Isothermal efficiency = isothermal power / input power = 56%","explain":"Only the isothermal share of the input is useful work; the rest is lost as heat and friction in the compressor."}],"order":4362}
]$cards$::jsonb);
